// Resend's inbound webhook payload is metadata only, no body/attachments.
// This just extracts routing info; the actual text gets fetched next.
const body = $json.body || {};
if (body.type !== 'email.received') {
  return [];
}
const data = body.data || {};
return [{
  json: {
    emailId: data.email_id || data.id || '',
    toAddress: (data.to && data.to[0]) || '',
    fromAddress: data.from || '',
    subject: data.subject || ''
  }
}];

// Combines routing info with the fetched body, and pulls the record type
// + id straight out of the plus-addressed reply-to tag
// (reply+mr-<uuid>@notify.traxkey.ai, oi- or inv- for the other two record
// types). This is the entire matching mechanism, deliberately no fuzzy
// sender/subject matching: the tag is unambiguous, so matching stays SQL
// -equivalent (a regex), never something Claude has to guess.
const routing = $('Parse Resend Payload').first().json;
const full = $json;
const bodyText = full.text || full.html || '';

const m = routing.toAddress.match(/reply\+(mr|oi|inv)-([0-9a-fA-F-]{36})@/);

return [{
  json: {
    ...routing,
    bodyText,
    recordType: m ? m[1] : null,
    recordId: m ? m[2] : null
  }
}];

