const rec = $json;
const reply = $('Combine Routing + Full Body').first().json;
const prompt = `A vendor replied to a job-assignment follow-up email for a property maintenance request.

Job: ${rec.description}
Category: ${rec.category || 'unspecified'}

Reply: ${reply.bodyText.slice(0, 2000)}

Respond with ONLY a JSON object (no markdown, no prose):
{ "classification": "confirmed" | "declined" | "other", "summary": "1 sentence plain-English summary of what the vendor said" }`;
return [{ json: { prompt, recordId: rec.id } }];

const raw = $json.content?.[0]?.text || '';
const cleaned = raw.replace(/```json/gi,'').replace(/```/g,'').trim();
const match = cleaned.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON in Claude response: ' + raw.slice(0,300));
const parsed = JSON.parse(match[0]);
// Values below are derived from an inbound email that anyone can send, by way
// of an LLM. Both the classification and any date are therefore untrusted
// input, and both reach SQL. Whitelist the classification and accept a date
// only in strict YYYY-MM-DD form, so nothing else can ever reach a query.
const isDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
const pick = (v, allowed) => allowed.includes(v) ? v : 'other';
const source = $('Build MR Prompt').first().json;
return [{ json: { recordId: source.recordId, classification: pick(parsed.classification, ['confirmed','declined','other']), summary: parsed.summary || '' } }];

parameters.query:
UPDATE traxkey.maintenance_requests
SET vendor_acknowledged_at = CASE WHEN '{{ $json.classification }}' = 'confirmed' THEN now() ELSE vendor_acknowledged_at END
WHERE id = '{{ $json.recordId }}';

