function rotr(x, n) { return ((x >>> n) | (x << (32 - n))) >>> 0; }

function sha256(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const withOne = new Uint8Array((((l + 9 + 63) >> 6) << 6));
  withOne.set(bytes);
  withOne[l] = 0x80;
  const bitLenLow = (l * 8) >>> 0;
  const bitLenHigh = Math.floor((l * 8) / 4294967296);
  const dv = new DataView(withOne.buffer);
  dv.setUint32(withOne.length - 4, bitLenLow, false);
  dv.setUint32(withOne.length - 8, bitLenHigh, false);
  const w = new Uint32Array(64);
  for (let i = 0; i < withOne.length; i += 64) {
    for (let t = 0; t < 16; t++) w[t] = dv.getUint32(i + t * 4, false);
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t-15],7) ^ rotr(w[t-15],18) ^ (w[t-15] >>> 3);
      const s1 = rotr(w[t-2],17) ^ rotr(w[t-2],19) ^ (w[t-2] >>> 10);
      w[t] = (w[t-16] + s0 + w[t-7] + s1) >>> 0;
    }
    let a=H[0],b=H[1],c=H[2],d=H[3],e=H[4],f=H[5],g=H[6],h=H[7];
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h=g; g=f; f=e; e=(d+temp1)>>>0; d=c; c=b; b=a; a=(temp1+temp2)>>>0;
    }
    H = [(H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,(H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0];
  }
  const out = new Uint8Array(32);
  const outDv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) outDv.setUint32(i * 4, H[i], false);
  return out;
}

function hmacSha256(keyBytes, msgBytes) {
  const blockSize = 64;
  if (keyBytes.length > blockSize) keyBytes = sha256(keyBytes);
  const k = new Uint8Array(blockSize);
  k.set(keyBytes);
  const opad = new Uint8Array(blockSize);
  const ipad = new Uint8Array(blockSize);
  for (let i = 0; i < blockSize; i++) { opad[i] = k[i] ^ 0x5c; ipad[i] = k[i] ^ 0x36; }
  const inner = sha256(concatBytes(ipad, msgBytes));
  return sha256(concatBytes(opad, inner));
}

function concatBytes(a, b) {
  const c = new Uint8Array(a.length + b.length);
  c.set(a, 0);
  c.set(b, a.length);
  return c;
}

function base64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

function bytesToBase64(bytes) {
  let bin = '';
  for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// Resend signs webhooks via Svix, not Stripe's scheme: the secret is
// "whsec_<base64>" (base64-DECODE it, don't use the raw string as the HMAC
// key like Stripe's), the signed content is "{svix-id}.{svix-timestamp}.
// {raw body}", and the header can carry several space-separated "v{n},<sig>"
// candidates -- accept a match against any of them, not just the first.
//
// Pulled from n8n's own env, never hardcoded in the workflow file (see
// SECURITY.md). Requires N8N_BLOCK_ENV_ACCESS_IN_NODE=false on this n8n
// instance -- no native Resend/Svix trigger node exists the way Stripe has
// one, so this is the one webhook in the project that still needs a
// hand-rolled verifier and therefore still needs that variable, same as the
// Stripe billing workflow did before it moved to the native Trigger node.
const RAW_SECRET = $env.RESEND_WEBHOOK_SECRET;
if (!RAW_SECRET) throw new Error('RESEND_WEBHOOK_SECRET not set in n8n environment');
const secretBytes = base64ToBytes(RAW_SECRET.replace(/^whsec_/, ''));

const item = $input.item;
const svixId = item.json.headers['svix-id'];
const svixTimestamp = item.json.headers['svix-timestamp'];
const svixSignature = item.json.headers['svix-signature'];
if (!svixId || !svixTimestamp || !svixSignature) {
  throw new Error('Missing svix-id/svix-timestamp/svix-signature header');
}

// Reject anything not recent. Without this a captured, valid request could
// be replayed indefinitely -- the signature alone never expires on its own.
const ageSeconds = Math.abs(Date.now() / 1000 - Number(svixTimestamp));
if (!Number.isFinite(ageSeconds) || ageSeconds > 300) {
  throw new Error('svix-timestamp outside tolerance, possible replay');
}

let rawBody;
if (item.binary && item.binary.data) {
  rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf-8');
} else {
  rawBody = typeof item.json.body === 'string' ? item.json.body : JSON.stringify(item.json.body);
}

const signedContent = `${svixId}.${svixTimestamp}.${rawBody}`;
const enc = new TextEncoder();
const expected = bytesToBase64(hmacSha256(secretBytes, enc.encode(signedContent)));

const candidates = svixSignature.split(' ').map(part => part.split(',')[1]).filter(Boolean);
if (!candidates.includes(expected)) {
  throw new Error('Inbound reply signature verification failed');
}

// item.json.body is no longer a parsed object once rawBody is
// enabled on the webhook node -- it stops feeding downstream JSON
// parsing entirely, which silently broke Parse Resend Payload's
// `body.type` check for every request, signed or not. Re-parse the
// exact bytes we just verified so every node after this one sees
// what it saw before rawBody existed.
return [{ json: { ...item.json, body: JSON.parse(rawBody) } }];
